UPDATE TB_SL_OPP_NEED SET job_cd=#{need.jobCode},grade_cd=#{need.gradeCode,jdbcType=VARCHAR},need_cnt=#{need.requiredCount},
  bgn_ym=replace(#{need.startMonth},'-',''),prd_mcnt=#{need.months},mon_mm=#{need.monthlyMm},expct_uprc=#{need.estimatedUnitPrice},
  mod_user_id=#{actor},mod_dttm=clock_timestamp() WHERE opp_id=#{id} AND need_sn=#{need.needSn}

