INSERT INTO TB_SL_APRV_HIST(opp_id,hist_sn,aprv_act_cd,prft_rt,act_rsn,reg_user_id,reg_dttm)
SELECT #{id},COALESCE(MAX(h.hist_sn),0)+1,#{status},#{profit},#{reason,jdbcType=VARCHAR},#{actor},clock_timestamp()
FROM TB_SL_APRV_HIST h WHERE h.opp_id=#{id}
